VW.pnewp=()=>{const h=_pur();return h.slice(0,h.indexOf('<div class="card sc">')).replace('<h2>Purchase</h2>','<h2>New Purchase</h2>')};
VW.pur=()=>`<h2>Purchase <small style="font-size:14px;opacity:.6">| Product Purchase</small></h2><div class="card" style="border-top-color:#3b8dbd"><div style="display:flex;flex-wrap:wrap;gap:2px">${[['🚚','New Purchase','pnewp'],['🚚','Purchase Return','rpur'],['≣','Purchase List','purl'],['≣','Purchase Order','pord'],['≣','Purchase Invoice List','purinv'],['≣','Purchase Return List','rpl']].map(x=>`<button class="t c6" style="width:130px" onclick="go('${x[2]}')"><i>${x[0]}</i>${x[1]}</button>`).join('')}</div></div>`;
VW.purl=()=>`<h2>Purchase List</h2><div class="card sc"><table><tr><th>Date</th><th>Inv</th><th>Vendor</th><th>Item</th><th>Qty</th><th>Cost</th><th>Amount</th></tr>${[...db.pur].reverse().flatMap(p=>p.items.map(l=>`<tr><td>${dt(p.date)}</td><td>${p.no}</td><td>${e(p.vendor)}</td><td>${e(l.name)}</td><td>${l.qty}</td><td>${m(l.cost)}</td><td>${m(l.qty*l.cost)}</td></tr>`)).join('')||'<tr><td>No purchase yet.</td></tr>'}</table></div>`;
VW.purinv=()=>`<h2>Purchase Invoice List</h2><div class="card sc"><table><tr><th>Date</th><th>No</th><th>Vendor</th><th>Total</th><th>Paid</th><th>Due</th><th></th></tr>${[...db.pur].reverse().map(p=>`<tr><td>${dt(p.date)}</td><td>${p.no}</td><td>${e(p.vendor)}</td><td>${m(p.total)}</td><td>${m(p.paid)}</td><td class="${p.total>p.paid?'low':''}">${m(p.total-p.paid)}</td><td><button class="btn" onclick="ppr(${p.no})">Print</button> ${p.total>p.paid?`<button class="btn g" onclick="ppay(${p.no})">Pay</button>`:''}</td></tr>`).join('')||'<tr><td>No invoice yet.</td></tr>'}</table></div>`;
function ppr(no){const p=db.pur.find(p=>p.no==no);$('#rc').innerHTML=`<center><b>${e(db.shop)}</b><br>Purchase Invoice #${p.no} · ${dt(p.date)}<br>${e(p.vendor)}</center><hr><table>${p.items.map(l=>`<tr><td>${e(l.name)}<br>${l.qty} × ${l.cost}</td><td align="right">${l.qty*l.cost}</td></tr>`).join('')}</table><hr><b>Total: ${m(p.total)}</b><br>Paid: ${m(p.paid)}<br>Due: ${m(p.total-p.paid)}`;setTimeout(()=>window.print(),50)}
function ppay(no){const p=db.pur.find(p=>p.no==no);M(`<h3>Pay invoice #${no}</h3><p>Due ${m(p.total-p.paid)}</p><input id="ppa" type="number" min="0" placeholder="Amount">`,()=>{const x=Math.min(+$('#ppa').value||0,p.total-p.paid);if(x<=0)return;p.paid+=x;const v=db.vendor.find(v=>v.name==p.vendor);if(v)v.payable=(v.payable||0)-x;save();X();render()},'Pay')}
VW.pord=()=>`<h2>Purchase Order</h2><div class="card"><div class="row"><select onchange="OV=this.value"><option value="">Select vendor</option>${db.vendor.map((v,i)=>`<option value="${i}" ${OV!==''&&OV==i?'selected':''}>${e(v.name)}</option>`).join('')}</select></div><div class="row"><select id="op">${popt()}</select><input id="oq" type="number" min="1" placeholder="Qty"><input id="oc" type="number" min="0" placeholder="Est. price"><button class="btn" onclick="oLine()">Add</button></div>${OC.map(l=>`<div class="ci">${e(l.name)} · ${l.qty} × ${m(l.cost)}</div>`).join('')}<br><button class="btn g" onclick="oSave()">Save order</button></div><div class="card sc"><table><tr><th>Date</th><th>No</th><th>Vendor</th><th>Total</th><th>Status</th><th></th></tr>${[...db.po].reverse().map(o=>`<tr><td>${dt(o.date)}</td><td>${o.no}</td><td>${e(o.vendor)}</td><td>${m(o.total)}</td><td>${o.status}</td><td>${o.status=='Pending'?`<button class="btn g" onclick="porec(${o.no})">Receive</button> <button class="btn r" onclick="db.po.find(x=>x.no==${o.no}).status='Cancelled';save();render()">×</button>`:''}</td></tr>`).join('')||'<tr><td>No order yet.</td></tr>'}</table></div>`;
function oLine(){const p=db.products.find(p=>p.id==$('#op').value),q=+$('#oq').value,c=+$('#oc').value;if(!p||q<1||c<=0){alert('Enter qty and price');return}OC.push({id:p.id,name:p.name+' '+p.v,qty:q,cost:c});render()}
function oSave(){const v=OV!==''?db.vendor[OV]:null;if(!v||!OC.length){alert('Select a vendor and add items');return}db.po.push({no:db.po.length+1,date:new Date().toISOString(),vendor:v.name,items:OC,total:sum(OC,l=>l.qty*l.cost),status:'Pending'});OC=[];save();render()}
function porec(no){const o=db.po.find(o=>o.no==no),v=db.vendor.find(v=>v.name==o.vendor);o.items.forEach(l=>{const p=db.products.find(p=>p.id==l.id);if(!p)return;p.cost=(p.stock*p.cost+l.qty*l.cost)/(p.stock+l.qty);p.stock+=l.qty});if(v)v.payable=(v.payable||0)+o.total;o.status='Received';db.pur.push({no:db.pur.length+1,date:new Date().toISOString(),vendor:o.vendor,items:o.items,total:o.total,paid:0});save();render()}
let PI='',PD='',PM='Cash',PN='',LC='';Object.assign(TI,{pnewp:'Product Purchase'});
const popt2=()=>db.products.filter(p=>p.active!==false&&(!LC||p.cat==LC)).map(p=>`<option value="${p.id}">${e(p.name)} ${e(p.v)} (${p.stock})</option>`).join('');
VW.pnewp=()=>{const t=sum(PC,l=>l.qty*l.cost),NL=(l,h,b)=>`<div class="ig" style="margin-bottom:8px"><span style="background:#001f3f;color:#fff;white-space:nowrap"><b>${l}</b></span>${h}${b?`<button style="background:#0073b7;color:#fff" onclick="${b}">+</button>`:''}</div>`;
return`<h2>Product Purchase <small style="font-size:14px;opacity:.6">| Purchase products according to purchase invoice</small></h2><div class="card" style="border-top-color:#3b8dbd">${NL('Invoice Number :',`<input id="pin" value="${e(PI)}" oninput="PI=this.value">`)}${NL('Supplier :',`<select style="border:0" onchange="PVn=this.value"><option value="">Select</option>${db.vendor.map((v,i)=>`<option value="${i}" ${PVn!==''&&PVn==i?'selected':''}>${e(v.name)}</option>`).join('')}</select>`,"mQ('vendor')")}${NL('Desc./IMEI :',`<input value="${e(PN)}" oninput="PN=this.value">`)}${NL('BarCode :',`<input id="lb" placeholder="Scan / enter code" onkeydown="if(event.key=='Enter')lscan()">`,'lscan()')}<div style="text-align:center;margin:10px 0"><b>Product</b> <button class="btn" onclick="go('pnew')">+</button></div>
<div class="row"><select id="lc" onchange="LC=this.value;$('#lpp').innerHTML=popt2();lpick()"><option value="">Cat</option>${db.cat.map(c=>`<option ${LC==c.name?'selected':''}>${e(c.name)}</option>`).join('')}</select><select id="lpp" onchange="lpick()">${popt2()}</select></div><div class="row"><input id="ld" placeholder="Description"></div><div class="row">${NL('Qty','<input id="lq" type="number" min="1" value="1" oninput="lt()">')}${NL('Price','<input id="lpr" type="number" min="0" placeholder="UnitPrice" oninput="lt()">')}${NL('Total','<input id="ltt" value="0" readonly>')}<button class="btn" style="flex:0 0 44px;height:38px" onclick="lAdd()">+</button></div>
${PC.map((l,i)=>`<div class="ci">${e(l.name)}${l.desc?' ('+e(l.desc)+')':''}<div><span style="flex:1">${l.qty} × ${m(l.cost)} = ${m(l.qty*l.cost)}</span><button class="q" onclick="PC.splice(${i},1);render()">×</button></div></div>`).join('')}<hr><div class="row">${NL('Total',`<input value="${t}" readonly>`)}${NL('Cash',`<input id="pd" type="number" min="0" placeholder="Paid" value="${e(PD)}" oninput="PD=this.value;pdue()">`)}${NL('Due',`<input id="pdu" readonly value="${Math.max(0,t-(+PD||0))}">`)}<select id="pm" onchange="PM=this.value">${['Cash','Bank','bKash','Nagad','Rocket'].map(x=>`<option ${PM==x?'selected':''}>${x}</option>`).join('')}</select></div><button class="btn" style="background:#6c7f9a" onclick="pSave()">Purchase</button> <button class="btn" style="background:#d81b60" onclick="pReset()">Reset</button> <button class="btn r" onclick="go('pur')">Cancel</button></div>`};
function lpick(){const p=db.products.find(p=>p.id==$('#lpp').value);if(p){$('#lpr').value=Math.round(p.cost);lt()}}
function lt(){$('#ltt').value=(+$('#lq').value||0)*(+$('#lpr').value||0)}
function pdue(){$('#pdu').value=Math.max(0,sum(PC,l=>l.qty*l.cost)-(+$('#pd').value||0))}
function lscan(){const v=$('#lb').value.trim().toLowerCase(),p=db.products.find(p=>p.bc==v||p.code.toLowerCase()==v);if(!p){alert('No product found for that code');return}LC='';$('#lc').value='';$('#lpp').innerHTML=popt2();$('#lpp').value=p.id;lpick();$('#lb').value='';$('#lq').focus()}
function lAdd(){const p=db.products.find(p=>p.id==$('#lpp').value),q=+$('#lq').value,c=+$('#lpr').value;if(!p||q<1||c<=0){alert('Select a product, qty and price');return}PC.push({id:p.id,name:p.name+' '+p.v,qty:q,cost:c,desc:$('#ld').value.trim()});render()}
function pReset(){PC=[];PI=PD=PN='';PM='Cash';PVn='';render()}
(function(){const st=document.createElement('style');st.textContent='.bc{background:#d2d6de;color:#444;padding:7px 10px;font-size:13px;margin-bottom:10px;border-radius:2px}.fr{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px}.fg{display:flex;flex:1 1 230px;min-width:0;border:1px solid var(--b);background:var(--in)}.fg>span{background:#001f3f;color:#fff;padding:8px 10px;white-space:nowrap;font-weight:700;display:grid;place-items:center;font-size:14px}.fg>input,.fg>select{border:0;flex:1;min-width:0}.fg>button{border:0;background:#0073b7;color:#fff;width:40px;font-size:18px;cursor:pointer}.fg.sm{flex:1 1 150px}.fg.ro{border-color:#00a65a}.fg.ro input{background:#eee;color:#333}.hr0{border:0;border-top:1px solid var(--b);margin:12px 0}';document.head.appendChild(st)})();
VW.pnewp=()=>{const t=sum(PC,l=>l.qty*l.cost),
G=(l,h,b,c='')=>`<div class="fg ${c}"><span>${l}</span>${h}${b?`<button onclick="${b}">+</button>`:''}</div>`;
return`<h2>🚚 Product Purchase <small style="font-size:14px;opacity:.6">| Purchase products according to purchase invoice</small></h2>
<div class="bc">Dashboard › Product › Purchase › New</div>
<div class="card" style="border-top-color:#3b8dbd">
<div class="fr">${G('Invoice Number :',`<input id="pin" value="${e(PI)}" oninput="PI=this.value">`)}${G('Supplier :',`<select onchange="PVn=this.value"><option value="">Select</option>${db.vendor.map((v,i)=>`<option value="${i}" ${PVn!==''&&PVn==i?'selected':''}>${e(v.name)}</option>`).join('')}</select>`,"mQ('vendor')")}${G('Desc./IMEI :',`<input value="${e(PN)}" oninput="PN=this.value">`)}${G('BarCode :',`<input id="lb" placeholder="Scan / enter code" onkeydown="if(event.key=='Enter')lscan()">`,'lscan()')}</div>
<hr class="hr0">
<div style="text-align:center;margin:6px 0 12px"><b>Product</b> <button class="btn" onclick="go('pnew')">+</button></div>
<div class="fr"><div class="fg sm"><select id="lc" onchange="LC=this.value;$('#lpp').innerHTML=popt2();lpick()"><option value="">Cat</option>${db.cat.map(c=>`<option ${LC==c.name?'selected':''}>${e(c.name)}</option>`).join('')}</select></div><div class="fg"><select id="lpp" onchange="lpick()">${popt2()}</select></div><div class="fg sm"><input id="ld" placeholder="Description"></div></div>
<div class="fr">${G('Qty','<input id="lq" type="number" min="1" value="1" oninput="lt()">','','sm')}${G('Price','<input id="lpr" type="number" min="0" placeholder="UnitPrice" oninput="lt()">','','sm')}${G('Total','<input id="ltt" value="0" readonly>','','sm ro')}<button class="btn" style="flex:0 0 44px" onclick="lAdd()">+</button></div>
${PC.map((l,i)=>`<div class="ci">${e(l.name)}${l.desc?' ('+e(l.desc)+')':''}<div><span style="flex:1">${l.qty} × ${m(l.cost)} = ${m(l.qty*l.cost)}</span><button class="q" onclick="PC.splice(${i},1);render()">×</button></div></div>`).join('')}
<hr class="hr0">
<div class="fr">${G('Total',`<input value="${t}" readonly>`,'','sm ro')}${G('Cash',`<input id="pd" type="number" min="0" placeholder="Paid" value="${e(PD)}" oninput="PD=this.value;pdue()">`,'','sm')}${G('Due',`<input id="pdu" readonly value="${Math.max(0,t-(+PD||0))}">`,'','sm ro')}<div class="fg sm"><select id="pm" onchange="PM=this.value">${['Cash','Bank','bKash','Nagad','Rocket'].map(x=>`<option ${PM==x?'selected':''}>${x}</option>`).join('')}</select></div></div>
<hr class="hr0">
<button class="btn" style="background:#6c7f9a" onclick="pSave()">Purchase</button> <button class="btn" style="background:#d81b60" onclick="pReset()">Reset</button> <button class="btn r" onclick="go('pur')">Cancel</button></div>`};
/* Product Distribute (new look) */
let DQ={},DS={};Object.assign(TI,{dist:'Product Distribute'});
const DG=(l,h,c='')=>`<div class="fg ${c}"><span>${l}</span>${h}</div>`;
VW.dist=()=>`<h2>➦ Product Distribute <small style="font-size:14px;opacity:.6">| Distribute products to shop</small></h2><div class="bc">Dashboard › Product › List › Distribute</div>
<div class="card" style="border-top-color:#3b8dbd"><h3>➦ Distribute Products</h3>
<div class="fr">${DG('Category :',`<select id="dc" onchange="PG=1;dr()"><option value="">Select</option>${db.cat.map(c=>`<option>${e(c.name)}</option>`).join('')}</select>`)}${DG('Vendor :',`<select id="dv" onchange="PG=1;dr()"><option value="">Select</option>${db.vendor.map(v=>`<option>${e(v.name)}</option>`).join('')}</select>`)}${DG('From :','<input id="df" type="date" onchange="PG=1;dr()">','sm')}${DG('To :','<input id="dtt" type="date" onchange="PG=1;dr()">','sm')}<button class="btn" style="flex:0 0 auto;background:#3b8dbd" onclick="dAll()">Show All</button></div>
<div class="ig" style="margin-bottom:14px"><input id="dbc" placeholder="Enter BarCode" onkeydown="if(event.key=='Enter')dScan()"><button style="background:#d81b60;color:#fff;font-size:15px;padding:0 14px" onclick="dScan()">BarCode</button></div>
<div class="row" style="align-items:center"><div style="flex:0 0 auto">Show <select id="dn" style="width:75px;display:inline-block" onchange="PG=1;dr()">${[10,25,50,100,300].map(n=>`<option>${n}</option>`).join('')}</select> entries</div><div style="flex:1 1 140px;text-align:right">Search: <input id="dse" style="width:140px;display:inline-block" oninput="PG=1;dr()"></div></div>
<div id="dtb"></div>
<hr class="hr0"><div class="row"><input id="dto" placeholder="Distribute to (shop / branch / outlet)"><button class="btn g" style="flex:0 0 auto" onclick="dGo()">Distribute selected (<span id="dsel">0</span>)</button></div></div>
<div class="card sc"><h3>Distribution history</h3><table><tr><th>Date</th><th>Item</th><th>Qty</th><th>To</th></tr>${[...db.dist].reverse().map(d=>`<tr><td>${dt(d.date)}</td><td>${e(d.name)}</td><td>${d.qty}</td><td>${e(d.to)}</td></tr>`).join('')||'<tr><td colspan="4">No distribution yet.</td></tr>'}</table></div>`;
function dr(){const g=i=>$('#'+i).value,c=g('dc'),v=g('dv'),f=g('df'),t=g('dtt'),q=g('dse').toLowerCase(),N0=+g('dn')||10,ds=p=>(p.date||new Date().toISOString()).slice(0,10);
const a=db.products.filter(p=>p.active!==false&&(!c||p.cat==c)&&(!v||p.vendor==v)&&(!f||ds(p)>=f)&&(!t||ds(p)<=t)&&(!q||(p.name+' '+p.v+' '+p.code+' '+p.bc+' '+(p.desc||'')).toLowerCase().includes(q))),N=Math.ceil(a.length/N0)||1;PG=Math.max(1,Math.min(PG,N));const s=(PG-1)*N0,pg=a.slice(s,s+N0);
$('#dtb').innerHTML=`<div class="sc"><table><tr><th>Select <input type="checkbox" style="width:auto" ${pg.length&&pg.every(p=>DS[p.id])?'checked':''} onchange="dSelAll(this.checked)"></th><th>Product ID</th><th>Product Name</th><th>Product Description</th><th>Entry Date</th><th>Qty</th><th>Dist. Qty</th></tr>${pg.map(p=>`<tr><td><input type="checkbox" style="width:auto" ${DS[p.id]?'checked':''} onchange="DS[${p.id}]=this.checked;dc2()"></td><td>${e(p.code)}</td><td>${e(p.name)} ${e(p.v)}</td><td>${e(p.desc)}</td><td>${dt(p.date||Date.now())}</td><td class="${p.stock<=p.min?'low':''}">${p.stock}</td><td><input type="number" min="1" max="${p.stock}" style="width:70px" value="${DQ[p.id]||1}" oninput="DQ[${p.id}]=+this.value"></td></tr>`).join('')||'<tr><td colspan="7" style="text-align:center">No data available in table</td></tr>'}</table></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px;flex-wrap:wrap;gap:8px"><span>Showing ${a.length?s+1:0} to ${Math.min(s+N0,a.length)} of ${a.length} entries</span><span><button class="btn" style="background:#fff;color:#337ab7;border:1px solid var(--b)" onclick="PG=Math.max(1,PG-1);dr()">Previous</button> <button class="btn" style="background:#fff;color:#337ab7;border:1px solid var(--b)" onclick="PG=Math.min(${N},PG+1);dr()">Next</button></span></div>`;dc2()}
function dc2(){const n=Object.keys(DS).filter(k=>DS[k]).length,el=$('#dsel');if(el)el.textContent=n}
function dSelAll(on){const N0=+$('#dn').value||10,c=$('#dc').value,v=$('#dv').value,q=$('#dse').value.toLowerCase();db.products.filter(p=>p.active!==false&&(!c||p.cat==c)&&(!v||p.vendor==v)&&(!q||(p.name+' '+p.v+' '+p.code+' '+p.bc).toLowerCase().includes(q))).slice((PG-1)*N0,PG*N0).forEach(p=>DS[p.id]=on);dr()}
function dAll(){['dc','dv','df','dtt','dse'].forEach(i=>$('#'+i).value='');PG=1;dr()}
function dScan(){const v=$('#dbc').value.trim().toLowerCase();if(!v)return;const p=db.products.find(p=>p.bc==v||p.code.toLowerCase()==v);if(!p){alert('No product found for that code');return}DQ[p.id]=DS[p.id]?(DQ[p.id]||1)+1:1;DS[p.id]=true;$('#dbc').value='';dAll()}
function dGo(){const to=$('#dto').value.trim(),ids=Object.keys(DS).filter(k=>DS[k]).map(Number),L=ids.map(id=>db.products.find(p=>p.id==id)).filter(Boolean);if(!L.length){alert('Select at least one product');return}if(!to){alert('Enter where to distribute');return}for(const p of L){const q=DQ[p.id]||1;if(q<1||q>p.stock){alert('Check quantity for '+p.name+' '+p.v+' (stock '+p.stock+')');return}}L.forEach(p=>{const q=DQ[p.id]||1;p.stock-=q;db.dist.push({date:new Date().toISOString(),name:p.name+' '+p.v,qty:q,to})});DS={};DQ={};save();render()}
/* Product Barcode (new look) */
let BS={},BQ={},BP=1;Object.assign(TI,{bcode:'Product Barcode'});
VW.bcode=()=>`<h2>▥ Product Barcode <small style="font-size:14px;opacity:.6">Generate &amp; print Barcode</small></h2><div class="bc">Dashboard › Product › BarCode</div>
<div class="card" style="border-top-color:#3b8dbd"><h3>🖶 Barcode Generation</h3>
<div class="fr"><div class="fg sm"><select id="bcat" onchange="BP=1;br()"><option value="">Select Category</option>${db.cat.map(c=>`<option>${e(c.name)}</option>`).join('')}</select></div><div class="fg sm"><select id="bven" onchange="BP=1;br()"><option value="">Select Vendor</option>${db.vendor.map(v=>`<option>${e(v.name)}</option>`).join('')}</select></div><div class="fg sm"><select id="bsz" onchange="BP=1;br()"><option value="">Select Size/Color</option>${[...new Set(db.products.map(p=>p.v).filter(Boolean))].map(x=>`<option>${e(x)}</option>`).join('')}</select></div>${DG('From :','<input id="bfr" type="date" onchange="BP=1;br()">','sm')}${DG('To :','<input id="bto" type="date" onchange="BP=1;br()">','sm')}<button class="btn" style="flex:0 0 auto;background:#3b8dbd" onclick="bAll()">Show All</button></div>
<div class="ig" style="margin-bottom:14px;max-width:360px"><input id="bid" placeholder="Product ID / Barcode" onkeydown="if(event.key=='Enter'){BP=1;br()}"><button style="background:#00a65a;color:#fff;font-size:15px;padding:0 16px" onclick="BP=1;br()">Search</button></div>
<div class="row" style="align-items:center"><div style="flex:0 0 auto">Show <select id="bnn" style="width:75px;display:inline-block" onchange="BP=1;br()">${[15,25,50,100,300].map(n=>`<option>${n}</option>`).join('')}</select> entries</div><div style="flex:1 1 140px;text-align:right">Search: <input id="bse" style="width:140px;display:inline-block" oninput="BP=1;br()"></div></div>
<div id="btb"></div><hr class="hr0"><button class="btn g" onclick="bGo()">🖶 Print selected labels (<span id="bsel">0</span>)</button></div>
<div class="card"><h3>Label preview</h3><div id="bpv" style="display:flex;flex-wrap:wrap"></div></div>`;
function bFilter(){const g=i=>$('#'+i).value,c=g('bcat'),v=g('bven'),z=g('bsz'),f=g('bfr'),t=g('bto'),id=g('bid').trim(),q=g('bse').toLowerCase(),ds=p=>(p.date||new Date().toISOString()).slice(0,10);return db.products.filter((p,i)=>p.active!==false&&(!c||p.cat==c)&&(!v||p.vendor==v)&&(!z||p.v==z)&&(!f||ds(p)>=f)&&(!t||ds(p)<=t)&&(!id||p.bc==id||p.code==id||String(i+1)==id)&&(!q||(p.name+' '+p.v+' '+p.code+' '+p.bc).toLowerCase().includes(q)))}
function br(){const N0=+$('#bnn').value||15,a=bFilter(),N=Math.ceil(a.length/N0)||1;BP=Math.max(1,Math.min(BP,N));const s=(BP-1)*N0,pg=a.slice(s,s+N0);
$('#btb').innerHTML=`<div class="sc"><table><tr><th>Select <input type="checkbox" style="width:auto" ${pg.length&&pg.every(p=>BS[p.id])?'checked':''} onchange="bSelAll(this.checked)"></th><th>Product ID</th><th>Product Name</th><th>Date</th><th>BarCode Quantity</th></tr>${pg.map(p=>`<tr><td><input type="checkbox" style="width:auto" ${BS[p.id]?'checked':''} onchange="BS[${p.id}]=this.checked;bc2()"></td><td>${e(p.code)}</td><td>${e(p.name)} ${e(p.v)}<br><small>${e(p.bc)}</small></td><td>${dt(p.date||Date.now())}</td><td><input type="number" min="1" style="width:70px" value="${BQ[p.id]||1}" oninput="BQ[${p.id}]=Math.max(1,+this.value||1)"></td></tr>`).join('')||'<tr><td colspan="5" style="text-align:center">No data available in table</td></tr>'}</table></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:10px;flex-wrap:wrap;gap:8px"><span>Showing ${a.length?s+1:0} to ${Math.min(s+N0,a.length)} of ${a.length} entries</span><span><button class="btn" style="background:#fff;color:#337ab7;border:1px solid var(--b)" onclick="BP=Math.max(1,BP-1);br()">Previous</button> <button class="btn" style="background:#fff;color:#337ab7;border:1px solid var(--b)" onclick="BP=Math.min(${N},BP+1);br()">Next</button></span></div>`;bc2()}
function bc2(){const L=db.products.filter(p=>BS[p.id]),el=$('#bsel');if(el)el.textContent=L.length;const pv=$('#bpv');if(pv)pv.innerHTML=L.map(lab).join('')||'<small style="opacity:.7;padding:6px">Select products to preview labels.</small>'}
function bSelAll(on){const N0=+$('#bnn').value||15;bFilter().slice((BP-1)*N0,BP*N0).forEach(p=>BS[p.id]=on);br()}
function bAll(){['bcat','bven','bsz','bfr','bto','bid','bse'].forEach(i=>$('#'+i).value='');BP=1;br()}
function bGo(){const L=db.products.filter(p=>BS[p.id]);if(!L.length){alert('Select at least one product');return}$('#rc').innerHTML=L.map(p=>lab(p).repeat(BQ[p.id]||1)).join('');setTimeout(()=>window.print(),50)}
/* Sales Report (new look) */
const ld=d=>{d=new Date(d);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')},
fd=d=>{d=new Date(d);const z=x=>String(x).padStart(2,'0'),h=d.getHours();return z(d.getDate())+'/'+z(d.getMonth()+1)+'/'+String(d.getFullYear()).slice(2)+' '+z(h%12||12)+':'+z(d.getMinutes())+' '+(h>=12?'PM':'AM')},
rn=x=>Math.round(x*100)/100;
let SRC='',SRCu='',SREm='',SRG=false,SRT='product',SRF=ld(Date.now()-7*864e5),SRTo=ld(Date.now()),SRH='';Object.assign(TI,{report:'Sales Report'});
(function(){const st=document.createElement('style');st.textContent='@media print{#rc.wide{width:auto;font:11px system-ui,sans-serif}#rc.wide table{width:100%;border-collapse:collapse}#rc.wide td,#rc.wide th{border:1px solid #999;padding:3px;text-align:left}}';document.head.appendChild(st)})();
const sOpt=(l,s)=>l.map(x=>`<option ${s==x?'selected':''}>${e(x)}</option>`).join('');
VW.report=()=>`<h2>🛍 Sales Report <small style="font-size:14px;opacity:.6">| Generate &amp; print sales report</small></h2><div class="bc">Dashboard › Report › Sales</div>
<div style="background:var(--card);border:1px solid #00a65a;border-radius:3px;margin-bottom:14px"><div style="background:#00a65a;color:#fff;padding:12px;font-size:18px;display:flex;justify-content:space-between">Sales Report<span style="cursor:pointer" onclick="go('dash')">✖</span></div>
<div style="padding:12px">
<div class="fr">${DG('Report :',`<select onchange="SRT=this.value">${[['product','Product Wise Sales'],['invoice','Invoice Wise Sales'],['customer','Customer Wise Sales'],['date','Date Wise Sales']].map(x=>`<option value="${x[0]}" ${SRT==x[0]?'selected':''}>${x[1]}</option>`).join('')}</select>`)}</div>
<div class="fr">${DG('Shop :',`<select><option>All Shop</option><option>${e(db.shop)}</option></select>`,'sm')}${DG('Cat :',`<select onchange="SRC=this.value"><option value="">All Category</option>${sOpt(db.cat.map(c=>c.name),SRC)}</select>`,'sm')}</div>
<div class="fr">${DG('User :','<select><option>All User</option></select>','sm')}${DG('From :',`<input type="date" value="${SRF}" onchange="SRF=this.value">`,'sm')}${DG('To :',`<input type="date" value="${SRTo}" onchange="SRTo=this.value">`,'sm')}</div>
<div class="fr">${DG('Customer :',`<select onchange="SRCu=this.value"><option value="">Select A Customer</option>${sOpt(db.customers.map(c=>c.name),SRCu)}</select>`,'sm')}${DG('Employee :',`<select onchange="SREm=this.value"><option value="">Select An Employee</option>${sOpt(db.hrm.map(h=>h.name),SREm)}</select>`,'sm')}</div>
<button class="btn g" onclick="sGen()">Generate Sales Report</button> <button class="btn" onclick="sGen('employee')">Employee Sales Report</button></div></div>`;
function sGen(f){const T=f||SRT,catOf=i=>(db.products.find(p=>p.id==i.id)||{}).cat,
a=db.sales.filter(s=>{const d=ld(s.date);return(!SRF||d>=SRF)&&(!SRTo||d<=SRTo)&&(!SRCu||s.cust==SRCu)&&(!SREm||s.emp==SREm)&&(!SRC||s.items.some(i=>catOf(i)==SRC))}),S=(r,k)=>rn(sum(r,x=>x[k])),th=h=>h.map(x=>`<th>${x}</th>`).join(''),td=r=>r.map(x=>`<td>${typeof x=='number'?rn(x):e(x)}</td>`).join('');
let title,head,rows=[],foot;
const F=(lead,idxs,trail)=>`<tr><th colspan="${lead}" style="text-align:center">Total</th>${idxs.map(k=>`<th>${S(rows,k)}</th>`).join('')}${'<th></th>'.repeat(trail)}</tr>`;
if(T=='product'){title='ProductWise';
a.forEach(s=>s.items.filter(i=>!SRC||catOf(i)==SRC).forEach(i=>{const p=db.products.find(p=>p.id==i.id)||{},c=db.customers.find(c=>c.name==s.cust),n=i.qty-(i.ret||0),sp=i.price*n,dis=s.sub?s.disc*sp/s.sub:0,tax=s.sub-s.disc>0?s.vat*(sp-dis)/(s.sub-s.disc):0,cost=i.cost*n;rows.push([s.no,p.code||'',i.name,s.cust?s.cust+(c&&c.phone?' ('+c.phone+')':''):'Walk-in',p.cat||'',p.vendor||'',i.qty,i.ret||0,cost,sp,dis,tax,sp-dis+tax,sp-dis-cost,fd(s.date)])}));
head=['Inv.ID','P.ID','P.Name','Customer(Phone)','Category','Vendor','Qty','Ref','CP','SP','Dis','Tax','Total','Profit','Date'];
const tcp=S(rows,8),tpf=S(rows,13);foot=`<tr><th colspan="6" style="text-align:center">Total Quantity</th>${[6,7,8,9,10,11,12,13].map(k=>`<th>${S(rows,k)}</th>`).join('')}<th>${tcp?rn(tpf/tcp*100):0}%<br><small>(Percentage)</small></th></tr>`}
else if(T=='invoice'){title='InvoiceWise';rows=a.map(s=>[s.no,s.cust||'Walk-in',sum(s.items,i=>i.qty-(i.ret||0)),s.sub,s.disc,s.vat,s.total,s.paid,s.due,prof(s),fd(s.date)]);head=['Inv.ID','Customer','Qty','Sub Total','Discount','VAT','Total','Paid','Due','Profit','Date'];foot=F(2,[2,3,4,5,6,7,8,9],1)}
else if(T=='customer'){title='CustomerWise';const g={};a.forEach(s=>{const k=s.cust||'Walk-in',r=g[k]=g[k]||[k,0,0,0,0,0,0];r[1]++;r[2]+=sum(s.items,i=>i.qty-(i.ret||0));r[3]+=s.total;r[4]+=s.paid;r[5]+=s.due;r[6]+=prof(s)});rows=Object.values(g);head=['Customer','Invoices','Qty','Total','Paid','Due','Profit'];foot=F(1,[1,2,3,4,5,6],0)}
else if(T=='employee'){title='EmployeeWise';const g={};a.forEach(s=>{const k=s.emp||'Not assigned',r=g[k]=g[k]||[k,0,0,0,0];r[1]++;r[2]+=sum(s.items,i=>i.qty-(i.ret||0));r[3]+=s.total;r[4]+=prof(s)});rows=Object.values(g);head=['Employee','Invoices','Qty','Total','Profit'];foot=F(1,[1,2,3,4],0)}
else{title='DateWise';const g={};a.forEach(s=>{const k=ld(s.date),r=g[k]=g[k]||[k,0,0,0,0,0,0];r[1]++;r[2]+=sum(s.items,i=>i.qty-(i.ret||0));r[3]+=s.disc;r[4]+=s.vat;r[5]+=s.total;r[6]+=prof(s)});rows=Object.keys(g).sort().map(k=>{const r=g[k];r[0]=dt(k+'T00:00');return r});head=['Date','Invoices','Qty','Discount','VAT','Sales Total','Profit'];foot=F(1,[1,2,3,4,5,6],0)}
SRH=`<div style="text-align:center"><h3 style="margin:0 0 6px">${title}</h3><div style="color:#666"><b>Shop Name :</b> ${e(db.shop)}</div><div style="color:#666"><b>Report Date :</b> ${SRF?dt(SRF+'T00:00').replace(/-/g,'/'):'-'} - ${SRTo?dt(SRTo+'T00:00').replace(/-/g,'/'):'-'} | <b>Print Date :</b> ${fd(Date.now()).replace(/(\d\d)\/(\d\d)\/(\d\d)/,'$1/$2/20$3')}</div></div><table style="font-size:13px;margin-top:10px"><tr>${th(head)}</tr>${rows.map(r=>`<tr>${td(r)}</tr>`).join('')||`<tr><td colspan="${head.length}" style="text-align:center">No data available</td></tr>`}${foot}</table>`;SRG=true;go('srep')}
(function(){const st=document.createElement('style');st.textContent='.srp{background:#fff;color:#222;margin:-14px;min-height:100vh}.srp table{font-size:13px}.srp td,.srp th{border:1px solid #ddd;padding:6px 5px;vertical-align:middle}.srp th{font-weight:700}.srp .nop{display:flex;gap:8px;padding:8px;background:#f4f4f4;border-bottom:1px solid #ddd}';document.head.appendChild(st)})();
Object.assign(TI,{srep:'Sales Report'});
VW.srep=()=>SRH?`<div class="srp"><div class="nop"><button class="btn" onclick="go('report')">← Back</button><button class="btn g" onclick="sPrint()">🖶 Print</button></div><div style="padding:10px 0 0;overflow-x:auto">${SRH}</div><div style="font-size:13px;margin:26px 8px 0;padding-bottom:16px"><b style="font-family:'Trebuchet MS',sans-serif;color:#3a82ad">ClassyPOS</b> © 2026 . All rights reserved.</div></div>`:'<p>No report generated.</p>';
function sPrint(){if(!SRH){alert('Generate a report first');return}const r=$('#rc');r.className='wide';r.innerHTML=SRH;setTimeout(()=>{window.print();r.className=''},50)}
const _r0=render;render=function(){_r0();if(V=='dist')dr();if(V=='bcode')br();if(V=='srep'){$('#top').innerHTML='';$('#bar').className=''}};
/* Login / users / sync */
Object.assign(TI,{users:'Users & Login'});
let CU=[],cpLoaded=false;
(function(){const g=go;go=function(v){cpLoaded=false;if(window.__USER&&window.__USER.role!='admin'&&!['home','pos','inv','cust','day','users'].includes(v)){alert('This page is for admin only.');return}g(v)}})();
VW.users=()=>{const u=window.__USER,ad=u.role=='admin';return`<h2>Users &amp; Login</h2><div class="card"><p>Logged in as <b>${e(u.email)}</b> (${u.role})</p><div class="row"><input id="op" type="password" placeholder="Current password"><input id="np" type="password" placeholder="New password (min 8)"><button class="btn g" onclick="cpPw()">Change password</button></div><button class="btn r" onclick="cpOut()">Logout</button></div>${ad?`<div class="card"><h3>Add user</h3><div class="row"><input id="ue" placeholder="Email"><input id="up" type="password" placeholder="Password (min 8)"><select id="ur"><option value="staff">Staff (sales only)</option><option value="admin">Admin</option></select><button class="btn g" onclick="cpAdd()">Add</button></div></div><div class="card sc"><table><tr><th>Email</th><th>Role</th><th></th></tr>${CU.map(x=>`<tr><td>${e(x.email)}</td><td>${x.role}</td><td><button class="btn r" onclick="cpDel('${e(x.email)}')">×</button></td></tr>`).join('')}</table></div>`:''}`};
async function cpUsers(){try{const r=await cpF('/api/users');if(r.ok){CU=await r.json();render()}}catch(x){}}
async function cpCall(p,o,okMsg){try{const r=await cpF(p,o),j=await r.json().catch(()=>({}));if(!r.ok){alert(j.error||'Failed');return false}if(okMsg)alert(okMsg);return true}catch(x){alert('Cannot reach server');return false}}
async function cpAdd(){if(await cpCall('/api/users',{method:'POST',body:JSON.stringify({email:$('#ue').value,password:$('#up').value,role:$('#ur').value})},'User added')){cpUsers()}}
async function cpDel(em){if(confirm('Delete '+em+'?')&&await cpCall('/api/users/'+encodeURIComponent(em),{method:'DELETE'})){cpUsers()}}
async function cpPw(){if(await cpCall('/api/password',{method:'POST',body:JSON.stringify({oldPassword:$('#op').value,newPassword:$('#np').value})},'Password changed')){$('#op').value=$('#np').value=''}}
async function cpOut(){try{await cpF('/api/logout',{method:'POST'})}catch(x){}localStorage.removeItem('classypos_token');location.reload()}
const _r1=render;render=function(){_r1();if(V=='users'&&window.__USER.role=='admin'&&!cpLoaded){cpLoaded=true;cpUsers()}};
setInterval(async()=>{if(cpDirty||cpBusy||document.hidden)return;try{const v=await(await cpF('/api/version')).json();if(v.version==null||v.version==window.__VER)return;const r=await cpF('/api/data'),j=await r.json();if(cpDirty||cpBusy||!j.db)return;db=j.db;vr=db.vat;window.__VER=j.version;if(['dash','day','inv'].includes(V)&&$('#md').className!='ov on')render()}catch(x){}},20000);
if(!window.__DB)save();
